def newman_prime(n):
    from sympy import isprime

    def prime_checker(n):
        if isprime(n):
            return n
        else:
            i = 1
            while True:
                test_no = (n ** 2) + i
                if isprime(test_no):
                    return test_no
                i += 1

    def prime_finder(n):
        if n == 1:
            return 2
        elif n == 2:
            return 1
        elif n % 2 != 0:
            return prime_checker(prime_finder(n - 2) ** 2)
        else:
            return prime_checker((prime_finder(n - 2) ** 2) - 2)

    return prime_finder(n)
